import React from 'react';
import { Link } from 'react-router-dom';
import { 
  LayoutDashboard, Users, ShoppingBag, CreditCard, 
  BarChart3, MessageSquare, Settings, LogOut, User, Shield,
  TrendingUp, Bell, FileText, Calendar, ShieldCheck,
  Database, Server, X
} from 'lucide-react';

// Option 1: Import local si Badge est dans le même dossier
// import Badge from './Badge';

// Option 2: Créez un composant Badge simple directement ici
const Badge = ({ children, color = 'primary', size = 'sm', className = '' }) => {
  const sizeClasses = {
    sm: 'px-2 py-0.5 text-xs',
    md: 'px-2.5 py-1 text-xs',
    lg: 'px-3 py-1.5 text-sm'
  };

  const colorClasses = {
    primary: 'bg-primary-500 text-white',
    secondary: 'bg-secondary-500 text-white',
    accent: 'bg-accent-500 text-white',
    success: 'bg-green-500 text-white',
    warning: 'bg-yellow-500 text-white',
    danger: 'bg-red-500 text-white',
    info: 'bg-blue-500 text-white',
    purple: 'bg-purple-500 text-white',
    pink: 'bg-pink-500 text-white'
  };

  return (
    <span className={`inline-flex items-center font-medium rounded-full ${sizeClasses[size]} ${colorClasses[color]} ${className}`}>
      {children}
    </span>
  );
};

const Sidebar = ({ sidebarOpen, currentPath, onLogout, isMobile }) => {
  const userEmail = localStorage.getItem('userEmail') || 'enzo@gmail.com';

  const navItems = [
    { to: "/dashboard", icon: LayoutDashboard, label: "Tableau de bord", exact: true },
    { to: "/dashboard/users", icon: Users, label: "Utilisateurs", badge: "42", badgeColor: "accent" },
    { to: "/dashboard/products", icon: ShoppingBag, label: "Produits", badge: "156", badgeColor: "secondary" },
    { to: "/dashboard/orders", icon: CreditCard, label: "Commandes", badge: "24", badgeColor: "primary" },
    { to: "/dashboard/analytics", icon: BarChart3, label: "Analytique" },
    { to: "/dashboard/messages", icon: MessageSquare, label: "Messages", badge: "3", badgeColor: "accent" },
    { to: "/dashboard/settings", icon: Settings, label: "Paramètres" },
  ];

  const secondaryNav = [
    { to: "/dashboard/reports", icon: FileText, label: "Rapports" },
    { to: "/dashboard/calendar", icon: Calendar, label: "Calendrier" },
    { to: "/dashboard/notifications", icon: Bell, label: "Notifications" },
  ];

  const systemNav = [
    { to: "/dashboard/system", icon: Server, label: "Système" },
    { to: "/dashboard/database", icon: Database, label: "Base de données" },
    { to: "/dashboard/backup", icon: ShieldCheck, label: "Sauvegarde" },
  ];

  return (
    <>
      {/* Overlay pour mobile */}
      {isMobile && sidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden"
          onClick={onLogout}
        />
      )}

      <aside className={`fixed inset-y-0 left-0 z-50 w-full md:w-64 bg-white/95 dark:bg-neutral-900/95 backdrop-blur-xl border-r border-neutral-200/50 dark:border-neutral-800/50 transform transition-transform duration-300 ${
        sidebarOpen ? 'translate-x-0' : '-translate-x-full'
      } md:translate-x-0`}>

        {/* En-tête mobile */}
        <div className="md:hidden p-4 border-b border-neutral-200/50 dark:border-neutral-800/50 flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="h-10 w-10 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center">
              <Shield className="h-6 w-6 text-white" />
