                        } transition-colors`}
                      >
                        <item.icon className="h-5 w-5" />
                        <span className="flex-1">{item.label}</span>
                        {item.badge && (
                          <Badge 
                            color={item.badgeColor} 
                            size="sm"
                            className={isActive ? 'bg-white/20 hover:bg-white/30' : ''}
                          >
                            {item.badge}
                          </Badge>
