            <button
              onClick={onLogout}
              className="flex items-center justify-center space-x-2 w-full px-4 py-3 rounded-xl border border-red-200 dark:border-red-800 text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors mb-3"
            >
              <LogOut className="h-5 w-5" />
              <span className="font-medium">Déconnexion</span>
            </button>

            <div className="hidden md:flex items-center justify-between text-xs text-neutral-500 dark:text-neutral-500">
              <span>v2.1.0</span>
              <span>© 2024 AdminPro</span>
            </div>
          </div>
        </div>
